CREATE POLICY "Candidate exact private media binding" ON storage.objects AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(bucket_id<>'personal-profile-media' OR EXISTS(SELECT 1 FROM public.personal_social_media m WHERE m.object_path=name AND m.user_id=auth.uid() AND (m.post_id IS NULL OR EXISTS(SELECT 1 FROM public.personal_social_posts p WHERE p.id=m.post_id AND p.user_id=auth.uid()))));
CREATE FUNCTION public.guard_personal_candidate_comment_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.post_id IS DISTINCT FROM OLD.post_id THEN RAISE EXCEPTION 'Comment identity and parent cannot be changed'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_personal_candidate_comment_identity() FROM PUBLIC;
CREATE TRIGGER personal_candidate_comment_identity BEFORE UPDATE ON public.personal_social_comments FOR EACH ROW EXECUTE FUNCTION public.guard_personal_candidate_comment_identity();
COMMENT ON POLICY "Candidate exact private media binding" ON storage.objects IS 'Unreleased owner-only candidate. Exact names only, orphan denial, no signed/public URL fallback. Existing vault-images remains unchanged and prevents production release.';